import itertools, sys, json

def find_partition(nums):
    nums = set(nums)
    # generate all valid triples (a,b,c) with a<b and a+b=c
    triples = []
    for a, b in itertools.combinations(nums, 2):
        c = a + b
        if c in nums and c not in (a, b):
            triples.append(tuple(sorted((a, b, c))))
    # remove duplicates
    triples = list(set(triples))
    # exact cover via recursive search
    used = set()
    solution = []
    def backtrack(start):
        if len(used) == len(nums):
            return True
        # pick the smallest unused number to prune
        for i, (a, b, c) in enumerate(triples):
            if a in used or b in used or c in used:
                continue
            # choose this triple
            used.update([a, b, c])
            solution.append((a, b, c))
            if backtrack(i+1):
                return True
            # backtrack
            used.difference_update([a, b, c])
            solution.pop()
        return False
    if backtrack(0):
        return solution
    return None

L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}
partition = find_partition(L)
if partition:
    print("Partition found:")
    for triple in partition:
        print(triple)
    # output witness
    witness = {"polarity": "positive", "evidence": {"path": "execution://witness"}, "data": {"triples": partition}}
    print("WITNESS:", json.dumps(witness))
else:
    print("No partition exists.")
    witness = {"polarity": "negative", "evidence": {"path": "execution://witness"}, "basis": "search", "search_exhausted": true, "method": "exact_cover"}
    print("WITNESS:", json.dumps(witness))

import sys, json
L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}
# Pre‑compute all valid triples (a,b,c) with a<b and a+b=c
triples = []
Llist = sorted(L)
Lset = set(Llist)
for i,a in enumerate(Llist):
    for b in Llist[i+1:]:
        c = a + b
        if c in Lset and c!=a and c!=b:
            triples.append((a,b,c))

# Build adjacency: for each number, which triples contain it
from collections import defaultdict
num_to_triples = defaultdict(list)
for t in triples:
    for x in t:
        num_to_triples[x].append(t)

solution = []
used = set()

sys.setrecursionlimit(10000)

def search():
    if len(used) == len(L):
        return True
    # pick the smallest unused number
    for x in Llist:
        if x not in used:
            start = x
            break
    for t in num_to_triples[start]:
        a,b,c = t
        if a in used or b in used or c in used:
            continue
        # commit
        used.update([a,b,c])
        solution.append(t)
        if search():
            return True
        # backtrack
        used.difference_update([a,b,c])
        solution.pop()
    return False

found = search()
if not found:
    print('WITNESS:', json.dumps({"polarity":"negative","evidence":{"path":"execution://witness"},"basis":"search","search_exhausted":true,"nodes_explored":null,"method":"depth‑first"}))
else:
    # produce positive witness
    witness_data = {"triples": solution}
    print('WITNESS:', json.dumps({"polarity":"positive","evidence":{"path":"execution://witness"},"data":witness_data}))
